package com.ecotrack.backend.goal;
import com.ecotrack.backend.activity.ActivityRepository; import com.ecotrack.backend.user.*; import org.springframework.stereotype.Service; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class GoalService{private final GoalRepository goals;private final UserRepository users;private final ActivityRepository acts;public GoalService(GoalRepository g,UserRepository u,ActivityRepository a){goals=g;users=u;acts=a;}
 public GoalDtos.GoalResponse create(String email,GoalDtos.CreateGoalRequest r){User u=users.findByEmailIgnoreCase(email).orElseThrow();double baseline=acts.total(u.getId(),r.startDate(),r.endDate());Goal g=new Goal();g.setUser(u);g.setTitle(r.title());g.setTargetReductionPercent(r.targetReductionPercent());g.setTargetEmission(r.targetEmission());g.setBaselineEmission(baseline);g.setCurrentEmission(baseline);g.setStartDate(r.startDate());g.setEndDate(r.endDate());goals.save(g);return to(g);}
 public List<GoalDtos.GoalResponse> list(String email){Long uid=users.findByEmailIgnoreCase(email).orElseThrow().getId();return goals.findByUserIdOrderByEndDateAsc(uid).stream().map(g->{g.setCurrentEmission(acts.total(uid,g.getStartDate(),java.time.LocalDate.now()));return to(g);}).toList();}
 public GoalDtos.GoalResponse get(String email,Long id){Long uid=users.findByEmailIgnoreCase(email).orElseThrow().getId();Goal g=goals.findById(id).filter(x->x.getUser().getId().equals(uid)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Goal not found"));g.setCurrentEmission(acts.total(uid,g.getStartDate(),java.time.LocalDate.now()));return to(g);}
 private GoalDtos.GoalResponse to(Goal g){double base=g.getBaselineEmission()==null?0:g.getBaselineEmission(),cur=g.getCurrentEmission()==null?0:g.getCurrentEmission();double progress=base<=0?0:Math.max(0,Math.min(100,((base-cur)/base)*100));return new GoalDtos.GoalResponse(g.getId(),g.getTitle(),g.getTargetReductionPercent(),g.getTargetEmission(),base,cur,Math.round(progress*10)/10.0,g.getStatus(),g.getStartDate(),g.getEndDate());}}
